#!/usr/bin/env bash
# =============================================================================
# AlphaCP — D15 FILE MANAGER PLUS v1.0  (live panel 0.75.x + paneld · 09 Oct 2026)
#
# Phase-2 Wave D15: File Manager plus — cPanel-style upload/compress/extract/chmod.
#   FILES: browser Upload (64 MB, staging -> agent ownership ke saath move),
#          Compress (.tar.gz), Extract (.tar.gz/.tgz, safe GNU tar), chmod
#   LIVE:  nginx client_max_body_size 64m (cpanel vhost, nginx -t gate) +
#          php-fpm upload ini + staging dir
# 6 files, multi-root. DB me KOI change nahi.
# Safety: backup (.bak-d15fm-<stamp>) -> install -> caches -> paneld gate ->
#   health -> AUTO-ROLLBACK.
# =============================================================================
set -Eeuo pipefail

D15_VERSION="1.0"
PANEL_ROOT="${PANEL_ROOT:-/usr/local/alphacp/panel}"
AGENT_ROOT="${AGENT_ROOT:-/usr/local/alphacp/agent}"
STAMP="$(date -u +%Y%m%d%H%M%S)"
LOG_FILE="/var/log/alphacp-d15-filemanager-plus.log"

C_B=$'\033[1m'; C_G=$'\033[32m'; C_R=$'\033[31m'; C_Y=$'\033[33m'; C_0=$'\033[0m'
say() { printf '%s\n' "$*"; }
log() { printf '%s [%s]\n' "$(date -u '+%F %T')Z" "$*" >>"${LOG_FILE}" 2>/dev/null || true; }
ok()  { log "OK   $*"; say "${C_G}[OK]${C_0} $*"; }
warn(){ log "WARN $*"; say "${C_Y}[!]${C_0} $*"; }
die() { log "FAIL $*"; say "${C_R}[x]${C_0} $*"; say "Log: ${LOG_FILE}"; exit 1; }

say ""
say "${C_B}== AlphaCP D15 FILE MANAGER PLUS v${D15_VERSION} ==${C_0}"
[[ "${EUID}" -eq 0 ]] || die "root chahiye: sudo bash $0"
[[ -d "${PANEL_ROOT}/public/assets" ]] || die "panel nahi mila: ${PANEL_ROOT}"
[[ -f "${PANEL_ROOT}/public/assets/panel.js" ]] || die "pehle theme-fix v1.2 install karo (panel.js missing) — COMMANDS.md dekho"
[[ -f "${AGENT_ROOT}/config/tasks.php" ]] || die "agent nahi mila: ${AGENT_ROOT}"
grep -q "db.user.revoke" "${AGENT_ROOT}/config/tasks.php" || die "agent tasks.php me D14 (db.user.revoke) nahi — pehle D14 wave install karo"

